using CouponBook.Business.Catalog;using Microsoft.AspNetCore.Mvc;namespace CouponBook.Api.Controllers;
[ApiController][Route("api")]public class CatalogController:ControllerBase{private readonly ICatalogService _c;public CatalogController(ICatalogService c)=>_c=c;[HttpGet("cities")]public async Task<IActionResult>Cities()=>Ok(await _c.GetCitiesAsync());[HttpGet("categories")]public async Task<IActionResult>Categories()=>Ok(await _c.GetCategoriesAsync());[HttpGet("books")]public async Task<IActionResult>Books([FromQuery]int? city,[FromQuery]int? category,[FromQuery]string? search)=>Ok(await _c.GetBooksAsync(city,category,search));[HttpGet("books/{id:int}")]public async Task<IActionResult>Book(int id){var x=await _c.GetBookAsync(id);return x==null?NotFound():Ok(x);}}
